import {bestBlock} from './code-index.js';
import {libraryEntries} from './code-hierarchy.js';
import {documents,findDocuments,findPractical,snippet,loadArchive} from './archive-store.js';
import {workNotes} from './notes-data.js';
import {searchNotes} from './notes-view.js';
import {syntaxTopics} from './syntax-data.js';
import {quickEntries} from './quick-data.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let deps={},results=[],selected=0,returnFocus=null;
const build=()=>[
 ...libraryEntries.map(e=>({type:'실행 위치 코드',title:e.title,description:e.description.replace('\n',' '),keywords:e.kind+' '+e.middle+' '+e.major+' '+(e.form||'')+(e.middle==='initialization'?' INITIALIZATION SET_INIT 초기값':''),action:'docs',id:'code/'+e.major+'/'+e.middle+'/'+e.id})),
 ...findPractical(document.querySelector('#universal-query')?.value||'').map(n=>({type:n.codeInfo?.hasCode?'구현 코드':'참고 문서',title:n.title,description:n.source+' · '+n.category,keywords:n.search,action:'docs',id:n.id,documentId:n.id})),
 ...documents.filter(n=>!n.codeInfo?.hasCode).map(n=>({type:'참고 문서',title:n.title,description:n.source+' · '+n.category,keywords:n.search,action:'docs',id:n.id,documentId:n.id})),
 ...workNotes.map(n=>({type:'실무 노트',title:n.title,description:n.summary,keywords:n.tags.join(' '),action:'notes',id:n.id})),
 ...syntaxTopics.map(n=>({type:'신문법 비교',title:n.title,description:n.summary,keywords:n.oldCode+' '+n.newCode,action:'syntax',id:n.id})),
 ...quickEntries.map(n=>({type:'빠른참조',title:n.code+' · '+n.title,description:n.description,keywords:n.tags,action:'quick',id:n.id})),
 ...deps.all().map(n=>({type:'템플릿',title:n.title,description:n.description,keywords:(n.tags||[]).join(' '),action:'template',id:n.id})),
 ...deps.references().map(n=>({type:'원문 자료',title:n.title,description:n.category+' · 원문 페이지 열기',keywords:n.category,action:'source',url:n.url}))
];
export const searchButton=()=>'<button class="universal-search-button" data-universal-search aria-label="전체 검색 열기"><span>전체 검색</span><kbd>Ctrl K</kbd></button>';
function close(){const d=document.querySelector('#universal-search');if(d){d.close();d.remove();returnFocus?.focus?.();}}
function render(){const query=document.querySelector('#universal-query').value.trim().toLowerCase(),scope=document.querySelector('#universal-scope').value;const words=query.split(/\s+/).filter(Boolean),memoMatches=new Set(query?searchNotes(query).map(n=>n.id):[]);const ranked=new Map(findPractical(query).map((d,i)=>[d.id,i]));let matches=build().filter(r=>scope==='전체'?r.type!=='참고 문서'&&r.type!=='원문 자료':r.type===scope).filter(r=>!query||words.every(w=>(r.title+' '+r.description+' '+r.keywords).toLowerCase().includes(w))||(r.action==='notes'&&memoMatches.has(r.id)));matches.sort((a,b)=>{const score=r=>r.documentId&&ranked.has(r.documentId)?10000-ranked.get(r.documentId):!query?({docs:6,notes:5,syntax:4,quick:3,template:2,source:1}[r.action]):r.title.toLowerCase()===query?20:r.title.toLowerCase().startsWith(query)?15:r.title.toLowerCase().includes(query)?10:2;return score(b)-score(a);});results=matches.slice(0,30);selected=Math.min(selected,Math.max(0,results.length-1));document.querySelector('#universal-count').textContent=query?`${matches.length}개 결과${matches.length>30?' · 상위 30개 표시':''}`:'키워드를 입력하거나 종류를 선택하세요.';document.querySelector('#universal-results').innerHTML=results.length?results.map((r,i)=>`<button id="universal-result-${i}" role="option" aria-selected="${selected===i}" class="universal-result ${selected===i?'active':''}" data-palette-index="${i}"><span class="tag">${r.type}</span><span><strong>${esc(r.title)}</strong><small>${esc(r.description)}</small></span><span aria-hidden="true">↵</span></button>`).join(''):'<p class="universal-empty">검색 결과가 없어요. 한국어 뜻이나 짧은 코드로 다시 찾아보세요.</p>';document.querySelector('#universal-query').setAttribute('aria-activedescendant',results.length?'universal-result-'+selected:'');}
function activate(){if(!results.length)return;document.querySelectorAll('.universal-result').forEach((b,i)=>{b.classList.toggle('active',selected===i);b.setAttribute('aria-selected',String(selected===i));});document.querySelector('#universal-query').setAttribute('aria-activedescendant','universal-result-'+selected);document.querySelector('#universal-result-'+selected)?.scrollIntoView({block:'nearest'});}
function choose(index){const r=results[index];if(!r)return;const query=document.querySelector('#universal-query').value;close();if(r.documentId){const d=documents.find(d=>d.id===r.documentId),block=d&&bestBlock(d,query);deps.navigate('docs',r.id+(block?'/block/'+block.index:''));return;}if(r.action==='template'){deps.openTemplate(r.id);return;}if(r.action==='source'){try{const url=new URL(r.url);if(url.protocol==='https:')window.open(url.href,'_blank','noopener,noreferrer');}catch{}return;}deps.navigate(r.action,r.id);}
export function openUniversalSearch(){if(document.querySelector('#universal-search')){document.querySelector('#universal-query').focus();return;}returnFocus=document.activeElement;const dialog=document.createElement('dialog');dialog.id='universal-search';dialog.className='universal-search';dialog.setAttribute('aria-label','전체 메뉴와 자료 검색');dialog.innerHTML=`<header><strong>전체 자료 검색</strong><button data-palette-close aria-label="전체 검색 닫기">닫기 ✕</button></header><div class="universal-input-row"><label for="universal-query" class="sr-label">전체 검색어</label><input id="universal-query" type="search" role="combobox" aria-expanded="true" aria-controls="universal-results" aria-autocomplete="list" autocomplete="off" placeholder="지급보류, READ, 트리, 임시저장, 타입 오류…"><label for="universal-scope" class="sr-label">검색 종류</label><select id="universal-scope">${['전체','실행 위치 코드','실무 노트','신문법 비교','빠른참조','템플릿','구현 코드','참고 문서','원문 자료'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="universal-count" class="universal-count" role="status"></div><div id="universal-results" role="listbox" aria-label="검색 결과"></div><footer>↑ ↓ 선택 · Enter 열기 · Esc 닫기 <span>설명·캡처는 ‘참고 문서’에서 찾을 수 있어요.</span></footer>`;document.body.append(dialog);selected=0;render();dialog.showModal();document.querySelector('#universal-query').focus();dialog.addEventListener('cancel',e=>{e.preventDefault();close();});}
export function bindUniversalSearch(d){deps=d;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();e.stopImmediatePropagation();openUniversalSearch();return;}if(e.target.id!=='universal-query')return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();selected=Math.max(0,Math.min(results.length-1,selected+(e.key==='ArrowDown'?1:-1)));activate();}if(e.key==='Enter'&&!e.isComposing){e.preventDefault();choose(selected);}},true);document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-universal-search'))openUniversalSearch();if(b.hasAttribute('data-palette-close'))close();if(b.dataset.paletteIndex!==undefined)choose(Number(b.dataset.paletteIndex));});document.addEventListener('input',e=>{if(e.target.id==='universal-query'){selected=0;render();}});document.addEventListener('change',e=>{if(e.target.id==='universal-scope'){selected=0;render();}});}

document.addEventListener('archive-ready',()=>{if(document.querySelector('#universal-search'))render();});
